export const ARTC = {}, ARTP = {};
export function loadArt() { const artKeys = Object.keys(ART); if (!artKeys.length) return Promise.resolve();
  return Promise.all(artKeys.map(k => new Promise(res => { const im = new Image(); im.onload = () => { const c = document.createElement('canvas'); c.width = im.width; c.height = im.height; c.getContext('2d').drawImage(im, 0, 0); c.hd = true; ARTC[k] = c; res(); }; im.onerror = () => { console.warn('art: could not load', k); res(); }; im.src = ART[k][0]; }))); }

